namespace {const Colour ink(0xff171a1d),gold(0xffffb36a),paper(0xfff5e9dd),copper(0xff9b4c21);void text(Graphics& g,String s,Rectangle<int> r,float sz,Colour c=paper,Justification j=Justification::centred){g.setColour(c);g.setFont(FontOptions(sz));g.drawFittedText(s,r,j,1);}void panel(Graphics& g,Rectangle<int> r,String title){auto f=r.toFloat();g.setGradientFill(ColourGradient(Colour(0xff5b3022),f.getX(),f.getY(),Colour(0xff282225),f.getRight(),f.getBottom(),false));g.fillRoundedRectangle(f,7);g.setColour(Colour(0xffce854a));g.drawRoundedRectangle(f.reduced(.5f),7,1);auto h=r.removeFromTop(25);g.setGradientFill(ColourGradient(Colour(0xffb56836),float(h.getX()),float(h.getY()),Colour(0xff63351e),float(h.getRight()),float(h.getBottom()),false));g.fillRoundedRectangle(h.toFloat().reduced(1),5);text(g,title,h.reduced(9,0),12,paper,Justification::centredLeft);}String note(float hz){if(hz<=0)return "--";int n=int(std::round(voices::midi(hz)));return String(voices::notes[(n%12+12)%12])+String(n/12-1);}}
