void VoicesEditor::Skin::drawRotarySlider(Graphics& g,int x,int y,int w,int h,float pos,float start,float end,Slider&){float radius=std::min(w,h)*.40f,cx=x+w*.5f,cy=y+h*.5f;auto box=Rectangle<float>(cx-radius,cy-radius,2*radius,2*radius);g.setColour(Colours::black.withAlpha(.5f));g.fillEllipse(box.expanded(3).translated(0,2));Path a;a.addCentredArc(cx,cy,radius+4,radius+4,0,start,end,true);g.setColour(Colour(0xff353238));g.strokePath(a,PathStrokeType(3));Path b;b.addCentredArc(cx,cy,radius+4,radius+4,0,start,start+(end-start)*pos,true);g.setColour(gold);g.strokePath(b,PathStrokeType(3,PathStrokeType::curved,PathStrokeType::rounded));g.setGradientFill(ColourGradient(Colour(0xffe8ba8b),cx-radius,cy-radius,Colour(0xff493326),cx+radius,cy+radius,false));g.fillEllipse(box);g.setColour(Colour(0xfff4c99f));g.drawEllipse(box,1);float ang=start+(end-start)*pos;g.setColour(ink);g.drawLine(cx+std::sin(ang)*radius*.35f,cy-std::cos(ang)*radius*.35f,cx+std::sin(ang)*radius*.82f,cy-std::cos(ang)*radius*.82f,2.5f);}
