void VoicesEditor::addKnob(int i,Rectangle<int> r){auto& s=voices::specs[i];Control c;c.knob=std::make_unique<Knob>();c.label=std::make_unique<Label>();c.knob->setSliderStyle(Slider::RotaryHorizontalVerticalDrag);c.knob->setTextBoxStyle(Slider::TextBoxBelow,false,76,17);c.knob->setTextValueSuffix(s.unit);c.knob->setDoubleClickReturnValue(true,s.def);c.knob->setBounds(r.withTrimmedTop(17));c.label->setBounds(r.removeFromTop(17));c.label->setFont(FontOptions(11.5f));c.label->setJustificationType(Justification::centred);c.label->setColour(Label::textColourId,paper);addAndMakeVisible(*c.knob);addAndMakeVisible(*c.label);c.attachment=std::make_unique<AP::SliderAttachment>(p.state,s.id,*c.knob);c.knob->menu=[this,i]{PopupMenu m;m.addItem(1,tr("Apprendre MIDI","MIDI Learn"));m.addItem(2,tr("Effacer l'affectation","Clear mapping"),p.cc[size_t(i)]>=0);m.showMenuAsync(PopupMenu::Options(),[safe=Component::SafePointer<VoicesEditor>(this),i](int v){if(safe!=nullptr){if(v==1)safe->p.learn=i;if(v==2)safe->p.cc[size_t(i)]=-1;safe->refresh();}});};c.knob->onDragStart=[this,i]{if(midiMode)p.learn=i;};controls.push_back(std::move(c));}
void VoicesEditor::addToggle(const char* id,Rectangle<int> r){auto b=std::make_unique<ToggleButton>();b->setBounds(r);addAndMakeVisible(*b);buttons.push_back(std::make_unique<AP::ButtonAttachment>(p.state,id,*b));toggles.push_back(std::move(b));}
void VoicesEditor::addCombo(const char* id,StringArray a,Rectangle<int> r){auto c=std::make_unique<ComboBox>();c->addItemList(a,1);c->setBounds(r);addAndMakeVisible(*c);choices.push_back(std::make_unique<AP::ComboBoxAttachment>(p.state,id,*c));combos.push_back(std::move(c));}
void VoicesEditor::layoutLanguage(){for(size_t i=0;i<controls.size();++i){auto& s=voices::specs[i];controls[i].label->setText(tr(s.fr,s.en),dontSendNotification);}save.setButtonText(tr("Sauvegarder","Save"));lang.setButtonText(p.french?"FR / EN":"EN / FR");search.setTextToShowWhenEmpty(tr("Rechercher un preset...","Search presets..."),paper);favoritesOnly.setButtonText(tr("Favoris","Favorites"));toggles[8]->setButtonText("Sync");toggles[0]->setButtonText("ON");StringArray scale=p.french?StringArray{tr("Chromatique",""),tr("Majeure",""),tr("Mineure",""),tr("Pentatonique maj.",""),tr("Pentatonique min.",""),tr("Dorien",""),tr("Personnalisée","")}:StringArray{"Chromatic","Major","Minor","Major pentatonic","Minor pentatonic","Dorian","Custom"};for(int i=0;i<scale.size();++i)combos[1]->changeItemText(i+1,scale[i]);combos[2]->changeItemText(1,tr("Naturel","Natural"));combos[2]->changeItemText(2,tr("Robotique","Hard tune"));refresh();}
void VoicesEditor::refresh(){browser.setButtonText(userName.isEmpty()?p.getProgramName(p.preset):userName);fav.setButtonText(p.favorites[size_t(p.preset)]?"*":"+");midi.setButtonText(p.learn>=0?tr("Bouger un CC","Move MIDI CC"):midiMode?"MIDI LEARN ON":"MIDI LEARN");repaint();}
void VoicesEditor::timerCallback(){for(int i=0;i<12;++i)toggles[size_t(i+9)]->setEnabled(int(p.value("scale"))==6);clipIn.setColour(TextButton::buttonColourId,p.inClip?Colour(0xffa62920):ink);clipOut.setColour(TextButton::buttonColourId,p.outClip?Colour(0xffa62920):ink);refresh();}
void VoicesEditor::loadPreset(int i){p.load(i);userName.clear();refresh();showBrowser(false);}
void VoicesEditor::showBrowser(bool b){browsing=b;for(auto* c:{static_cast<Component*>(&search),static_cast<Component*>(&category),static_cast<Component*>(&favoritesOnly),static_cast<Component*>(&list)}){c->setVisible(b);if(b)c->toFront(false);}if(b){filter();search.grabKeyboardFocus();}}
void VoicesEditor::filter(){rows.clear();userFiles.clear();auto q=search.getText();int c=category.getSelectedId();for(int i=0;i<100;++i)if(c!=12&&(c<=1||i/10==c-2)&&(!favoritesOnly.getToggleState()||p.favorites[size_t(i)])&&(q.isEmpty()||p.getProgramName(i).containsIgnoreCase(q)||String(voices::categories[i/10]).containsIgnoreCase(q)))rows.push_back(i);if((c<=1||c==12)&&!favoritesOnly.getToggleState()){for(auto f:p.presetDir().findChildFiles(File::findFiles,false,"*.voicespreset"))if(q.isEmpty()||f.getFileNameWithoutExtension().containsIgnoreCase(q)){rows.push_back(100+int(userFiles.size()));userFiles.push_back(f);}}list.updateContent();list.repaint();}
int VoicesEditor::BrowserModel::getNumRows(){return int(e.rows.size());}void VoicesEditor::BrowserModel::paintListBoxItem(int i,Graphics& g,int w,int h,bool selected){if(i>=int(e.rows.size()))return;int v=e.rows[size_t(i)];g.fillAll(selected?copper:ink);String s=v<100?String(e.p.favorites[size_t(v)]?"*  ":"   ")+e.p.getProgramName(v)+"  /  "+voices::categories[v/10]:e.userFiles[size_t(v-100)].getFileNameWithoutExtension()+"  /  USER";text(g,s,{12,0,w-24,h},13,paper,Justification::centredLeft);}void VoicesEditor::BrowserModel::listBoxItemClicked(int i,const MouseEvent&){if(i>=int(e.rows.size()))return;int v=e.rows[size_t(i)];if(v<100)e.loadPreset(v);else{MemoryBlock b;auto f=e.userFiles[size_t(v-100)];if(f.loadFileAsData(b)){e.p.setStateInformation(b.getData(),int(b.getSize()));e.userName=f.getFileNameWithoutExtension();e.layoutLanguage();e.showBrowser(false);}}}
void VoicesEditor::savePreset(){auto dir=p.presetDir();dir.createDirectory();auto f=dir.getChildFile("User "+Time::getCurrentTime().formatted("%Y%m%d-%H%M%S")+".voicespreset");MemoryBlock b;p.getStateInformation(b);if(f.replaceWithData(b.getData(),b.getSize())){userName=f.getFileNameWithoutExtension();refresh();}}
